// Text capture (spec 0003 R8-R14, R17): mint the agent's own token
// (ADR 0042 -- composing a capture is the agent's own act, hh_agent with
// the capturing member's id, never the member's own role), gather
// context the same way a real model would need it, call the model
// gateway with the mounted prompt (R11d -- read from the file, never
// pasted into this JSON), validate the response against the declared
// schema, and either record a balanced transaction or continue the
// clarifying exchange (R17: a further question if one is still needed,
// never the same question twice).
const crypto = require('crypto');
const http = require('http');
const fs = require('fs');
const { URL } = require('url');

const PG = 'http://postgrest:3000';

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintToken(role, memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role, member_id: memberId, exp: Math.floor(Date.now() / 1000) + 60 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname,
      port: u.port,
      path: u.pathname + u.search,
      method,
      headers: Object.assign(
        { 'Content-Type': 'application/json' },
        headers,
        bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}
      ),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try {
          parsed = data ? JSON.parse(data) : null;
        } catch (e) {
          parsed = data;
        }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

function formatAmount(minor, currency) {
  const major = (minor / 100).toFixed(2);
  return currency === 'EUR' ? `${major} €` : `${major} ${currency}`;
}

async function main() {
  const item = $input.first().json;
  const { member_id, chat_id, message_thread_id, text, language_hint, channel_message_id, update_id } = item;
  const isRu = language_hint === 'ru';

  const agentToken = mintToken('hh_agent', member_id);
  const auth = { Authorization: `Bearer ${agentToken}` };

  const [settingsRes, memberRes, merchantsRes, aliasesRes, accountsRes, openConvRes, memoryRes] = await Promise.all([
    httpJson('GET', `${PG}/household_setting`, auth),
    httpJson('GET', `${PG}/member?id=eq.${member_id}&select=default_payment_account_id`, auth),
    httpJson('GET', `${PG}/account?type=eq.expense&active=eq.true&select=id,name`, auth),
    httpJson('GET', `${PG}/merchant_alias?select=alias,merchant_id`, auth),
    httpJson('GET', `${PG}/account?active=eq.true&select=id,name,type`, auth),
    httpJson('GET', `${PG}/conversation?member_id=eq.${member_id}&kind=eq.clarification&closed_at=is.null`, auth),
    httpJson('GET', `${PG}/agent_memory?or=(member_id.eq.${member_id},member_id.is.null)&select=content`, auth),
  ]);

  const settings = {};
  (settingsRes.body || []).forEach((s) => { settings[s.key] = s.value; });
  const currency = settings.default_currency || 'EUR';
  const timezone = settings.timezone || 'UTC';

  const categoryAccounts = merchantsRes.body || []; // expense-type accounts
  const categorySlugs = categoryAccounts.map((a) => a.name);

  const merchantByIdRes = await httpJson('GET', `${PG}/merchant?active=eq.true&select=id,name,default_category_id`, auth);
  const merchants = merchantByIdRes.body || [];
  const merchantById = {};
  merchants.forEach((m) => { merchantById[m.id] = m; });
  const merchantByName = {};
  merchants.forEach((m) => { merchantByName[m.name] = m; });

  const aliasToMerchantName = {};
  (aliasesRes.body || []).forEach((a) => {
    const m = merchantById[a.merchant_id];
    if (m) aliasToMerchantName[a.alias] = m.name;
  });

  const merchantDefaultCategorySlug = {};
  merchants.forEach((m) => {
    if (m.default_category_id) {
      const cat = categoryAccounts.find((c) => c.id === m.default_category_id);
      if (cat) merchantDefaultCategorySlug[m.name] = cat.name;
    }
  });

  const allAccounts = accountsRes.body || [];
  const knownAccountNames = allAccounts.map((a) => a.name);

  let conversation = (openConvRes.body || [])[0] || null;
  let history = [];
  if (conversation) {
    const capsRes = await httpJson('GET', `${PG}/capture?conversation_id=eq.${conversation.id}&order=sequence.asc&select=direction,raw_text`, auth);
    history = (capsRes.body || []).map((c) => ({ direction: c.direction, text: c.raw_text }));
  }

  const memoryNotes = (memoryRes.body || []).map((m) => m.content);

  const today = new Date().toLocaleDateString('en-CA', { timeZone: timezone });

  const context = {
    currency,
    today,
    known_merchant_aliases: aliasToMerchantName,
    merchant_default_category: merchantDefaultCategorySlug,
    known_categories: categorySlugs,
    known_accounts: knownAccountNames,
  };
  if (history.length) context.conversation_history = history;
  if (memoryNotes.length) context.memory = memoryNotes;

  const systemPrompt = fs.readFileSync('/prompts/capture-text/v1/system.md', 'utf8');
  // The worked examples are the prompt's own few-shot demonstrations
  // (ADR 0025) -- sent as real prior turns, not just kept in the
  // repository as documentation nobody's request actually includes.
  // A real model was found (spec 0003 T15's golden set) to ignore the
  // bare-amount convention and the terse payment-method-hint shape
  // without seeing them demonstrated, prose alone was not enough.
  const examples = JSON.parse(fs.readFileSync('/prompts/capture-text/v1/examples.json', 'utf8'));
  const fewShotMessages = examples.flatMap((ex) => ([
    { role: 'user', content: JSON.stringify({ text: ex.input, context: ex.context || {} }) },
    { role: 'assistant', content: JSON.stringify(ex.output) },
  ]));
  const promptVersion = 'capture-text@1';
  const modelName = $env.MODEL_TEXT_EXTRACTION || 'meowhub/capture-text-stub';

  let modelRes = null;
  let gatewayFailed = false;
  try {
    modelRes = await httpJson('POST', `${$env.OPENROUTER_BASE_URL}/chat/completions`, {}, {
      model: modelName,
      messages: [
        { role: 'system', content: systemPrompt },
        ...fewShotMessages,
        { role: 'user', content: JSON.stringify({ text, context }) },
      ],
    });
    if (!modelRes || modelRes.status < 200 || modelRes.status >= 300) {
      gatewayFailed = true;
    }
  } catch (e) {
    gatewayFailed = true;
  }

  // A20: the gateway itself is unreachable or erroring -- distinct from
  // A28's schema violation, and from A18's genuine ambiguity. Neither of
  // those is the member's problem to answer a question about; this one
  // is nobody's problem to answer at all, so no question is asked.
  if (gatewayFailed) {
    await insertCapture({ conversation_id: null, sequence: 1, direction: 'inbound', raw_text: text, state: 'unparsed' });
    const notice = isRu
      ? 'Не получилось обработать это сейчас — ничего не потеряно, разберёмся позже.'
      : "Couldn't process that right now — nothing is lost, it will be handled.";
    return [{ json: { chat_id, message_thread_id, text: notice } }];
  }

  let parsed = null;
  try {
    const raw = modelRes.body.choices[0].message.content;
    const candidate = JSON.parse(raw);
    const statusOk = candidate && (candidate.status === 'resolved' || candidate.status === 'question');
    const inferredOk = candidate && Array.isArray(candidate.inferred_fields);
    const resolvedOk = candidate && candidate.status === 'resolved' ? typeof candidate.amount_minor === 'number' : true;
    const questionOk = candidate && candidate.status === 'question' ? typeof candidate.question === 'string' && candidate.question.length > 0 : true;
    parsed = (statusOk && inferredOk && resolvedOk && questionOk) ? candidate : null;
  } catch (e) {
    parsed = null;
  }

  const nextSeq = history.length + 1;

  async function ensureConversation() {
    if (conversation) return conversation;
    const created = await httpJson('POST', `${PG}/conversation`, Object.assign({ Prefer: 'return=representation' }, auth), {
      member_id, kind: 'clarification', step: 'awaiting_answer', payload: {},
    });
    conversation = created.body[0];
    return conversation;
  }

  async function insertCapture(fields) {
    return httpJson('POST', `${PG}/capture`, Object.assign({ Prefer: 'return=representation' }, auth), Object.assign({
      member_id, chat_id: String(chat_id), channel_message_id: channel_message_id ? String(channel_message_id) : null, kind: 'text',
    }, fields));
  }

  // A28/A20: no usable, schema-valid response at all -- unparsed, with a
  // generic question, exactly like a genuine "question" outcome.
  if (!parsed || parsed.status === 'question') {
    const question = parsed && parsed.question
      ? parsed.question
      : (isRu ? 'Не могу разобрать это сообщение — что вы потратили?' : "I couldn't make sense of that — what did you spend?");

    await ensureConversation();
    await insertCapture({ conversation_id: conversation.id, sequence: nextSeq, direction: 'inbound', raw_text: text, state: 'unparsed' });

    const alreadyAsked = history.some((h) => h.direction === 'outbound' && h.text === question);
    if (alreadyAsked) {
      // R0f/A41: never ask the same question again without new information.
      return [{ json: { chat_id, message_thread_id, text: null, silent: true } }];
    }

    await insertCapture({ conversation_id: conversation.id, sequence: nextSeq + 1, direction: 'outbound', raw_text: question });
    await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { last_touched_at: new Date().toISOString() });

    return [{ json: { chat_id, message_thread_id, text: question } }];
  }

  // Resolved: compose the balanced transaction.
  const inferred = parsed.inferred_fields || [];

  let merchantId = null;
  if (parsed.merchant) {
    const existing = merchantByName[parsed.merchant];
    if (existing) {
      merchantId = existing.id;
    } else {
      const created = await httpJson('POST', `${PG}/merchant`, Object.assign({ Prefer: 'return=representation' }, auth), { name: parsed.merchant });
      merchantId = created.body[0].id;
      await httpJson('POST', `${PG}/merchant_alias`, Object.assign({ Prefer: 'return=minimal' }, auth), { merchant_id: merchantId, alias: text });
    }
  }

  let categorySource = 'model';
  let categoryAccountId = null;
  if (parsed.category_slug) {
    const existingCategory = categoryAccounts.find((a) => a.name === parsed.category_slug);
    if (existingCategory) {
      categoryAccountId = existingCategory.id;
    } else {
      const createdCat = await httpJson('POST', `${PG}/account`, Object.assign({ Prefer: 'return=representation' }, auth), {
        type: 'expense', name: parsed.category_slug, reviewed: false,
      });
      categoryAccountId = createdCat.body[0].id;
      const label = parsed.category_slug.replace(/-/g, ' ');
      await httpJson('POST', `${PG}/translation`, Object.assign({ Prefer: 'return=minimal' }, auth), [
        { slug: parsed.category_slug, language: 'en', display_name: label },
        { slug: parsed.category_slug, language: 'ru', display_name: label },
      ]);
    }
    if (merchantId && merchantByName[parsed.merchant] && merchantByName[parsed.merchant].default_category_id === categoryAccountId && !inferred.includes('category')) {
      categorySource = 'merchant_default';
    }
  }

  let paymentAccountId = null;
  if (parsed.payment_method_hint) {
    const hint = parsed.payment_method_hint.toLowerCase();
    const match = allAccounts.find((a) => a.name.toLowerCase().includes(hint) || hint.includes(a.name.toLowerCase()));
    paymentAccountId = match ? match.id : null;
  }
  if (!paymentAccountId) {
    paymentAccountId = memberRes.body[0] && memberRes.body[0].default_payment_account_id;
  }
  if (!paymentAccountId) {
    const question = isRu ? 'С какого счёта оплачено?' : 'Which account was this paid from?';
    await ensureConversation();
    await insertCapture({ conversation_id: conversation.id, sequence: nextSeq, direction: 'inbound', raw_text: text, state: 'unparsed' });
    await insertCapture({ conversation_id: conversation.id, sequence: nextSeq + 1, direction: 'outbound', raw_text: question });
    return [{ json: { chat_id, message_thread_id, text: question } }];
  }

  const date = parsed.date || today;

  const txnRes = await httpJson('POST', `${PG}/transaction`, Object.assign({ Prefer: 'return=representation' }, auth), {
    date,
    submitter: member_id,
    source: 'text',
    merchant_id: merchantId,
    category_source: categorySource,
    model: modelName,
    prompt_version: promptVersion,
    original_amount: parsed.original_amount_minor,
    original_currency: parsed.original_currency,
    note: parsed.note,
    inferred_fields: inferred,
  });
  const transactionId = txnRes.body[0].id;

  await httpJson('POST', `${PG}/posting`, Object.assign({ Prefer: 'return=minimal' }, auth), [
    { transaction_id: transactionId, account_id: paymentAccountId, amount: -parsed.amount_minor, currency: parsed.currency || currency },
    { transaction_id: transactionId, account_id: categoryAccountId, amount: parsed.amount_minor, currency: parsed.currency || currency },
  ]);

  if (conversation) {
    await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { closed_at: new Date().toISOString() });
  }
  await insertCapture({ conversation_id: conversation ? conversation.id : null, sequence: nextSeq, direction: 'inbound', raw_text: text, state: 'resolved', transaction_id: transactionId });

  const categoryLabel = parsed.category_slug ? parsed.category_slug.replace(/-/g, ' ') : (isRu ? 'без категории' : 'uncategorised');
  const amountText = formatAmount(parsed.amount_minor, parsed.currency || currency);
  const merchantPart = parsed.merchant ? ` — ${parsed.merchant}` : '';
  const confirmation = isRu
    ? `${amountText}${merchantPart} (${categoryLabel})`
    : `${amountText}${merchantPart} (${categoryLabel})`;

  // R23/ADR 0035: the confirmation carries inline buttons for the
  // common next actions, each with a typed equivalent that reaches
  // the exact same code path (A32) -- Normalize turns a tapped button
  // into the same shape as if its typed equivalent had been sent.
  const buttons = [
    { text: isRu ? '✅ Подтвердить' : '✅ Approve', data: `confirm:${transactionId}` },
    { text: isRu ? '✏️ Категория' : '✏️ Fix category', data: `fixcat:${transactionId}` },
    { text: isRu ? '↩️ Отменить' : '↩️ Undo', data: 'undo' },
  ];
  return [{ json: { chat_id, message_thread_id, text: confirmation, transaction_id: transactionId, buttons } }];
}

return main();
